import sys, copy, statistics
sys.path.insert(0, 'tools')
import belief_state as bs
data = bs.load_belief_ledgers()
mats, evals, hyps = data['materials'], data['evaluations'], data['hypotheses']
def pq(h): return h.get('primary_question_id') or (h.get('question_ids') or [''])[0]
def pm(st, q): return {i['hypothesis_id']: float(i.get('posterior', 0.0)) for i in st['questions'][q]['hypotheses']}
sup = {'reacq': [], 'flagonly': []}
for eid, e in evals.items():
    if e.get('verdict') != 'supports': continue
    h = hyps.get(e.get('target_hypothesis_id'))
    if not h or pq(h) not in ('Q-001','Q-002','Q-003'): continue
    if e.get('evidence_type') == 'reproducible_script' and (e.get('script_command') or '').strip(): continue
    c = bs.classify_evaluation_verification(e, mats)
    if c == 'all_verified': sup['reacq'].append(eid)
    elif c in ('zero_verified','no_materials','mixed_verified'): sup['flagonly'].append(eid)
for gated, lab in ((False, 'P_t'), (True, 'P_gate')):
    B = bs.compute_belief_state(data=data, receiver_gated=gated)
    Bm = {q: pm(B, q) for q in ('Q-001','Q-002','Q-003')}
    for k, ids in sup.items():
        ds = []
        for eid in ids:
            d2 = copy.deepcopy(data); d2['evaluations'].pop(eid, None)
            st = bs.compute_belief_state(data=d2, receiver_gated=gated)
            h = hyps[evals[eid]['target_hypothesis_id']]; q = pq(h)
            ds.append(Bm[q].get(h['hypothesis_id'],0.0) - pm(st, q).get(h['hypothesis_id'],0.0))
        print(lab, k, 'n=%d mean=%.6g max=%.6g' % (len(ds), statistics.mean(ds), max(ds)))

